create table t1(a integer primary key, b text default 'x', c real check (c > 0), d, unique(b, d));
create index i1 on t1(c, d) where d is not null;
create view v1 as select a, b, t1.c as cc from t1 where t1.d > 0;
create table t2(x int references t1(a), y text, z as (x * 2), foreign key (y) references t1(b));
create trigger tr1 after insert on t1 begin insert into t2(x, y) values (new.a, new.b); update t2 set y = new.b where x = new.a; delete from t2 where t2.x = old.a; end;
insert into t1 values (1, 'one', 1.5, 10), (2, 'two', 2.5, 20);
alter table t1 rename to t1new;
select name, tbl_name, sql from sqlite_schema order by name;
alter table t1new rename column b to bee;
select name, sql from sqlite_schema order by name;
alter table t1new rename column a to aa;
select name, sql from sqlite_schema order by name;
select * from t1new;
alter table t1new add column e text default 'zz';
alter table t1new add column f int not null default 5 check (f > 0);
select * from t1new;
select sql from sqlite_schema where name = 't1new';
alter table t1new drop column e;
select sql from sqlite_schema where name = 't1new';
select * from t1new;
alter table t1new drop column aa;
alter table t1new drop column bee;
alter table t1new add column g int primary key;
alter table t1new add column h unique;
alter table t1new add column i int not null;
alter table v1 rename to v2;
alter table nosuch rename to x;
alter table t2 rename column nosuch to w;
alter table sqlite_schema rename to x;
alter table t2 rename to t1new;
pragma integrity_check;
